<# Prueft Laufanzeigen und Aufgabenplanung. Meldet nur Befunde per Windows-Toast, ohne Zusatzmodul. #>
[CmdletBinding()] param([switch]$Probe)
$ErrorActionPreference = 'Stop'; $root = Split-Path $PSScriptRoot -Parent; $betrieb = Join-Path $root 'betrieb'; $logs = Join-Path $betrieb 'logs'; New-Item -ItemType Directory -Force $logs | Out-Null; $anzeige = Join-Path $betrieb 'laufanzeige.md'; New-Item -ItemType File -Force $anzeige | Out-Null; $conf = Join-Path $betrieb 'waechter.conf'; $befund = Join-Path $betrieb 'waechter.md'; $anzeigen = @($anzeige); $takte = @(); $praefixe = @(); $befunde = @()
if (Test-Path $conf) { $nr=0; foreach ($zeile in Get-Content $conf) { $nr++; $teile = (($zeile -replace '#.*$').Trim() -split '\s+'); if (-not $teile[0]) { continue }; switch ($teile[0]) { 'anzeige' { if ($teile.Count -eq 2 -and (Test-Path $teile[1])) {$anzeigen += $teile[1]} else {$befunde += "waechter.conf Zeile $nr: anzeige <pfad> ungültig"} }; 'takt' { if ($teile.Count -eq 3 -and $teile[2] -match '^\d+$') {$takte += ,@($teile[1],[int]$teile[2])} else {$befunde += "waechter.conf Zeile $nr: takt <name> <stunden> ungültig"} }; 'praefix' { if ($teile.Count -eq 2) {$praefixe += $teile[1]} else {$befunde += "waechter.conf Zeile $nr: praefix <text> ungültig"} }; default {$befunde += "waechter.conf Zeile $nr: unbekannte Direktive '$($teile[0])'"} } } }
$seit = (Get-Date).AddDays(-1); foreach ($datei in $anzeigen) { if (Test-Path $datei) { $befunde += @(Get-Content $datei | Where-Object { $_ -match '\| FEHLER \|' -and $_.Substring(0,[Math]::Min(16,$_.Length)) -ge $seit.ToString('yyyy-MM-dd') } | ForEach-Object { "$(Split-Path $datei -Leaf): $_" }) } }
foreach ($takt in $takte) { $treffer = @(foreach ($datei in $anzeigen) { if (Test-Path $datei) { Get-Content $datei | Where-Object { $_ -like "*| $($takt[0]) | OK*" } | Select-Object -Last 1 } }) | Select-Object -Last 1; if (-not $treffer) {$befunde += "$($takt[0]): noch nie gelaufen laut Laufanzeige"} else { try {$zeit=[datetime]::ParseExact($treffer.Split('|')[0].Trim(),'yyyy-MM-dd HH:mm',$null); if (((Get-Date)-$zeit).TotalHours -gt $takt[1]) {$befunde += "$($takt[0]): letzter Lauf vor mehr als $($takt[1])h"}} catch {$befunde += "$($takt[0]): Zeitstempel nicht lesbar"} } }
foreach ($praefix in $praefixe) { foreach ($job in Get-ScheduledTask -ErrorAction SilentlyContinue | Where-Object TaskName -like "$praefix*") { $info = $job | Get-ScheduledTaskInfo; if ($info.LastTaskResult -ne 0) {$befunde += "Aufgabe $($job.TaskName): letzter Exitcode $($info.LastTaskResult)"} } }
$jetzt = Get-Date -Format 'yyyy-MM-dd HH:mm'; @('# Wächter-Befund',"Stand: $jetzt",'') + $(if ($befunde) {$befunde | ForEach-Object { "- $_" }} else {'Nichts auffaellig.'}) | Set-Content $befund
function Toast([string]$Titel,[string]$Text) { $log=Join-Path $logs 'waechter-mitteilungen.log'; if ($env:MR_TEST -eq '1') { Add-Content $log "$jetzt MITTEILUNG (Test, nicht ausgelöst): $Titel: $Text"; return }; try { [Windows.UI.Notifications.ToastNotificationManager,Windows.UI.Notifications,ContentType=WindowsRuntime] > $null; $xml = New-Object Windows.Data.Xml.Dom.XmlDocument; $xml.LoadXml("<toast><visual><binding template='ToastGeneric'><text>$Titel</text><text>$Text</text></binding></visual></toast>"); [Windows.UI.Notifications.ToastNotificationManager]::CreateToastNotifier('Windows PowerShell').Show([Windows.UI.Notifications.ToastNotification]::new($xml)) } catch { Add-Content $log "$jetzt MITTEILUNG FEHLGESCHLAGEN: $Titel: $Text" } }
if ($Probe) { Toast 'Wächter (Probe)' 'Das ist eine Probemeldung von waechter.ps1 --Probe.'; Write-Output 'Probemeldung ausgelöst.'; exit 0 }; if ($befunde) { Toast 'Wächter meldet FEHLER' $befunde[0] }
